PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_n
)
{
    .reg .b32 %r_tx, %r_ty, %r_bx, %r_by, %r_n, %r_kt, %r_ktn;
    .reg .b32 %r_tid, %r_r0, %r_c, %r_k, %r_row, %r_col, %r_tmp;
    .reg .b32 %r_row0, %r_col0, %r_sA, %r_sB, %r_saddr, %r_saddrA, %r_saddrB;
    .reg .b32 %r_aBase, %r_bBase, %r_ab, %r_bb, %r_buf, %r_nbuf;
    .reg .b64 %rd_A, %rd_B, %rd_C, %rd_off, %rd_addr, %rd_rowstride;
    .reg .b64 %rd_Arow, %rd_Bbase, %rd_gA, %rd_gB;
    .reg .f32 %f_a0, %f_a1, %f_a2, %f_a3, %f_b0, %f_b1, %f_b2, %f_b3;
    .reg .f32 %f_pa0, %f_pa1, %f_pa2, %f_pa3;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3, %f_acc4, %f_acc5, %f_acc6, %f_acc7;
    .reg .f32 %f_acc8, %f_acc9, %f_acc10, %f_acc11, %f_acc12, %f_acc13, %f_acc14, %f_acc15;
    .reg .pred %p1, %p2, %p3;
    // 64x64 CTA tile, 16-wide K tile; each thread computes a 4x4 sub-tile.
    // Double-buffered cp.async pipeline (sm_89): B K-tiles are prefetched with 16B
    // cp.async and A K-tiles with ld.global.v4 into registers one tile ahead,
    // overlapping global-memory latency with the 4x4 register-blocked FMA loop.
    // sA[k][r] holds A transposed, sB[k][c]; both padded to 68 floats/row, 2 stages.
    // N % 64 == 0 is asserted by the launcher, so all tile loads are provably
    // in-bounds and 16B-aligned; no staging predicates are required.
    .shared .align 16 .b8 sA[8704];
    .shared .align 16 .b8 sB[8704];
    mov.u32 %r_tx, %tid.x;
    mov.u32 %r_ty, %tid.y;
    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;
    ld.param.u64 %rd_A, [param_A];
    ld.param.u64 %rd_B, [param_B];
    ld.param.u64 %rd_C, [param_C];
    ld.param.u32 %r_n, [param_n];
    shl.b32 %r_bx, %r_bx, 6;
    shl.b32 %r_by, %r_by, 6;
    mov.u32 %r_sA, sA;
    mov.u32 %r_sB, sB;
    shl.b32 %r_tid, %r_ty, 4;
    add.u32 %r_tid, %r_tid, %r_tx;
    shl.b32 %r_row0, %r_ty, 2;
    add.u32 %r_row0, %r_row0, %r_by;
    shl.b32 %r_col0, %r_tx, 2;
    add.u32 %r_col0, %r_col0, %r_bx;
    shl.b32 %r_aBase, %r_ty, 4;
    add.u32 %r_aBase, %r_aBase, %r_sA;
    shl.b32 %r_bBase, %r_tx, 4;
    add.u32 %r_bBase, %r_bBase, %r_sB;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.f32 %f_acc4, 0f00000000;
    mov.f32 %f_acc5, 0f00000000;
    mov.f32 %f_acc6, 0f00000000;
    mov.f32 %f_acc7, 0f00000000;
    mov.f32 %f_acc8, 0f00000000;
    mov.f32 %f_acc9, 0f00000000;
    mov.f32 %f_acc10, 0f00000000;
    mov.f32 %f_acc11, 0f00000000;
    mov.f32 %f_acc12, 0f00000000;
    mov.f32 %f_acc13, 0f00000000;
    mov.f32 %f_acc14, 0f00000000;
    mov.f32 %f_acc15, 0f00000000;
    // ---- precompute per-thread staging bases: A transposed float4, B float4 ----
    shr.b32 %r_r0, %r_tid, 2;
    and.b32 %r_c, %r_tid, 3;
    shl.b32 %r_c, %r_c, 2;
    add.u32 %r_row, %r_by, %r_r0;
    mul.lo.u32 %r_tmp, %r_row, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_c;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Arow, %rd_A, %rd_off;
    mul.lo.u32 %r_saddrA, %r_c, 68;
    add.u32 %r_saddrA, %r_saddrA, %r_r0;
    shl.b32 %r_saddrA, %r_saddrA, 2;
    add.u32 %r_saddrA, %r_saddrA, %r_sA;
    shr.b32 %r_k, %r_tid, 4;
    and.b32 %r_c, %r_tid, 15;
    shl.b32 %r_c, %r_c, 2;
    add.u32 %r_col, %r_bx, %r_c;
    mul.lo.u32 %r_tmp, %r_k, %r_n;
    add.u32 %r_tmp, %r_tmp, %r_col;
    mul.wide.u32 %rd_off, %r_tmp, 4;
    add.u64 %rd_Bbase, %rd_B, %rd_off;
    mul.lo.u32 %r_saddrB, %r_k, 68;
    add.u32 %r_saddrB, %r_saddrB, %r_c;
    shl.b32 %r_saddrB, %r_saddrB, 2;
    add.u32 %r_saddrB, %r_saddrB, %r_sB;
    mov.u32 %r_kt, 0;
    mov.u32 %r_buf, 0;
    mov.u32 %r_nbuf, 4352;
