    ld.global.v4.f32 {%f_pa0, %f_pa1, %f_pa2, %f_pa3}, [%rd_Arow];
    cp.async.cg.shared.global [%r_saddrB], [%rd_Bbase], 16;
    cp.async.commit_group;
