    add.u32 %r_saddr, %r_saddrA, %r_buf;
    st.shared.f32 [%r_saddr], %f_pa0;
    st.shared.f32 [%r_saddr+272], %f_pa1;
    st.shared.f32 [%r_saddr+544], %f_pa2;
    st.shared.f32 [%r_saddr+816], %f_pa3;
