def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float32 and B.dtype == torch.float32
        assert A.dim() == 2 and B.dim() == 2
        assert A.shape[1] == B.shape[0]
        assert A.is_contiguous() and B.is_contiguous()
        M, K = A.shape
        _, N = B.shape
        assert M == K == N  # Reference uses a single square N x N matmul.
        assert N % 64 == 0  # Specialized: vectorized 16B-aligned tile staging requires N multiple of 64.

        C = torch.empty((M, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()
        tile = 16
        cta_tile = 64
        grid_x = (N + cta_tile - 1) // cta_tile
        grid_y = (M + cta_tile - 1) // cta_tile
        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, 1),
            block=(tile, tile, 1),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
